1|// Web Audio engine behind AmbienceController. One lazily created
2|// AudioContext; loops run through BufferSource loop, so fades on the
3|// audio clock still finish in a background tab.
4|import type { AmbienceEngine, AmbienceVoice } from "./ambience-controller";
5|import type { AmbienceSource } from "@/core/ambience";
6|
7|let shared: AudioContext | null = null;
8|const decoded = new Map<string, Promise<AudioBuffer>>();
9|
10|function context(): AudioContext {
11|  if (!shared) shared = new AudioContext();
12|  return shared;
13|}
14|
15|// First source canPlayType rates "probably" or "maybe", else the first.
16|function pickSource(sources: AmbienceSource[]): AmbienceSource | null {
17|  if (sources.length === 0) return null;
18|  try {
19|    const probe = new Audio();
20|    return (
21|      sources.find((source) => {
22|        const verdict = probe.canPlayType(source.type);
23|        return verdict === "probably" || verdict === "maybe";
24|      }) ?? sources[0]!
25|    );
26|  } catch {
27|    return sources[0]!;
28|  }
29|}
30|
31|export class WebAmbienceEngine implements AmbienceEngine {
32|  load(sources: AmbienceSource[]): Promise<AudioBuffer> {
33|    const picked = pickSource(sources);
34|    if (!picked) return Promise.reject(new Error("no ambience sources"));
35|    let pending = decoded.get(picked.src);
36|    if (!pending) {
37|      pending = (async () => {
38|        const response = await fetch(picked.src);
39|        if (!response.ok) throw new Error(`ambience fetch failed: ${picked.src}`);
40|        return context().decodeAudioData(await response.arrayBuffer());
41|      })();
42|      decoded.set(picked.src, pending);
43|      pending.then(null, () => void decoded.delete(picked.src));
44|    }
45|    return pending;
46|  }
47|
48|  start(handle: unknown, gain: number, fadeSec: number): AmbienceVoice {
49|    const ctx = context();
50|    const source = ctx.createBufferSource();
51|    source.buffer = handle as AudioBuffer;
52|    source.loop = true;
53|    const out = ctx.createGain();
54|    out.gain.value = 0;
55|    source.connect(out);
56|    out.connect(ctx.destination);
57|    const at = ctx.currentTime;
58|    if (fadeSec > 0) {
59|      // Sine curve in, so the crossfade keeps equal power with the
60|      // outgoing voice fading out over the same span.
61|      const curve = new Float32Array(32).map((_, i) => gain * Math.sin(((i / 31) * Math.PI) / 2));
62|      out.gain.setValueCurveAtTime(curve, at, fadeSec);
63|    } else {
64|      out.gain.setValueAtTime(gain, at);
65|    }
66|    source.start(at);
67|    return {
68|      ramp(next: number, sec: number) {
69|        const now = ctx.currentTime;
70|        out.gain.cancelScheduledValues(now);
71|        out.gain.setValueAtTime(out.gain.value, now);
72|        out.gain.linearRampToValueAtTime(next, now + Math.max(0, sec));
73|      },
74|      stop(sec: number) {
75|        const now = ctx.currentTime;
76|        const span = Math.max(0, sec);
77|        out.gain.cancelScheduledValues(now);
78|        out.gain.setValueAtTime(out.gain.value, now);
79|        out.gain.linearRampToValueAtTime(0, now + span);
80|        source.onended = () => {
81|          source.disconnect();
82|          out.disconnect();
83|        };
84|        try {
85|          source.stop(now + span);
86|        } catch {
87|          // Already stopped; onended still disconnects.
88|        }
89|      },
90|    };
91|  }
92|
93|  unlock(): Promise<void> {
94|    return context().resume().then(() => undefined);
95|  }
96|}

