1|// Rain level, volume, and mute logic against an injected engine, so
2|// tests use a fake. The controller owns fades: fade in from off,
3|// crossfade between playing levels, fade out to off. Nothing starts
4|// before unlock (the user gesture); pending loads never race, so only
5|// the latest level starts and at most two voices are alive at once.
6|import {
7|  AMBIENCES,
8|  CROSSFADE_SEC,
9|  DEFAULT_AMBIENCE_VOLUME,
10|  FADE_IN_SEC,
11|  FADE_OUT_SEC,
12|  MUTE_FADE_SEC,
13|  VOLUME_RAMP_SEC,
14|  ambienceGain,
15|  levelById,
16|} from "@/core/ambience";
17|import type { Ambience, AmbienceSource } from "@/core/ambience";
18|
19|export interface AmbienceVoice {
20|  ramp(gain: number, sec: number): void;
21|  stop(fadeSec: number): void;
22|}
23|
24|export interface AmbienceEngine {
25|  load(sources: AmbienceSource[]): Promise<unknown>;
26|  start(handle: unknown, gain: number, fadeSec: number): AmbienceVoice;
27|  unlock(): Promise<void>;
28|}
