30|export class AmbienceController {
31|  private levelId = "off";
32|  private volume = DEFAULT_AMBIENCE_VOLUME;
33|  private muted = false;
34|  private unlocked = false;
35|  private voice: AmbienceVoice | null = null;
36|  private pendingId: string | null = null;
37|  private seq = 0;
38|
39|  constructor(
40|    private engine: AmbienceEngine,
41|    private ambience: Ambience = AMBIENCES[0]!,
42|  ) {}
43|
44|  private targetGain(levelId: string): number {
45|    return ambienceGain(this.volume, this.muted, levelById(this.ambience, levelId)?.gainDb ?? 0);
46|  }
47|
48|  private play(levelId: string): void {
49|    const level = levelById(this.ambience, levelId);
50|    if (!level || !this.unlocked) return;
51|    const at = ++this.seq;
52|    this.pendingId = levelId;
53|    const sources = level.sources;
54|    void this.engine.load(sources).then((handle) => {
55|      if (at !== this.seq) return;
56|      this.pendingId = null;
57|      const prev = this.voice;
58|      this.voice = null;
59|      // From off there is nothing to crossfade, so fade in instead.
60|      if (prev) prev.stop(CROSSFADE_SEC);
61|      this.voice = this.engine.start(handle, this.targetGain(levelId), prev ? CROSSFADE_SEC : FADE_IN_SEC);
62|    });
63|  }
