67|    if (next === this.levelId) return;
68|    this.levelId = next;
69|    if (next === "off") {
70|      this.seq += 1;
71|      this.pendingId = null;
72|      const prev = this.voice;
73|      this.voice = null;
74|      prev?.stop(FADE_OUT_SEC);
75|      return;
76|    }
77|    this.play(next);
78|  }
