1|// Pure rain ambience model: levels, fades, prefs. No DOM, no env, no
2|// network, so tests run it directly. Adding fireplace later is one entry.
3|export interface AmbienceSource {
4|  src: string;
5|  type: string;
6|}
7|
8|export interface AmbienceLevel {
9|  id: string;
10|  label: string;
11|  color: string;
12|  sources: AmbienceSource[];
13|  gainDb: number;
14|}
15|
16|export interface Ambience {
17|  id: string;
18|  label: string;
19|  levels: AmbienceLevel[];
20|}
21|
22|export const DEFAULT_AMBIENCE_VOLUME = 0.4;
23|export const FADE_IN_SEC = 1.5;
24|export const FADE_OUT_SEC = 1.2;
25|export const CROSSFADE_SEC = 2;
26|export const MUTE_FADE_SEC = 0.3;
27|export const VOLUME_RAMP_SEC = 0.1;
28|
29|const WEBM: AmbienceSource = { src: "", type: "audio/webm; codecs=opus" };
30|
31|function rainLevel(id: string, color: string): AmbienceLevel {
32|  return {
33|    id,
34|    label: id,
35|    color,
36|    sources: [
37|      { ...WEBM, src: `/ambience/v1/rain-${id}.webm` },
38|      { src: `/ambience/v1/rain-${id}.m4a`, type: "audio/mp4" },
39|    ],
40|    gainDb: 0,
41|  };
42|}
43|
44|export const AMBIENCES: Ambience[] = [
45|  {
46|    id: "rain",
47|    label: "Rain",
48|    levels: [
49|      { id: "off", label: "off", color: "#9aa4ae", sources: [], gainDb: 0 },
50|      rainLevel("drizzle", "#5ab8f0"),
51|      rainLevel("moderate", "#f2c230"),
52|      rainLevel("storm", "#e5484d"),
53|    ],
54|  },
55|];
56|
57|export function levelById(ambience: Ambience, levelId: string): AmbienceLevel | null {
58|  return ambience.levels.find((level) => level.id === levelId) ?? null;
59|}
60|
61|// Cycle order is the levels array: off -> drizzle -> moderate -> storm.
62|export function nextLevel(ambience: Ambience, levelId: string): string {
63|  const at = ambience.levels.findIndex((level) => level.id === levelId);
64|  if (at < 0) return "drizzle";
65|  return ambience.levels[(at + 1) % ambience.levels.length]?.id ?? levelId;
66|}
67|
68|export function ambienceLabel(ambience: Ambience, levelId: string): string {
69|  const level = levelById(ambience, levelId);
70|  return `${ambience.label}: ${level?.label ?? levelId}`;
71|}
72|
73|// Muted is silence; otherwise the clamped volume scaled by the dB trim.
74|export function ambienceGain(volume: number, muted: boolean, gainDb: number): number {
75|  if (muted) return 0;
76|  const clamped = Number.isFinite(volume) ? Math.min(1, Math.max(0, volume)) : 0;
77|  return clamped * 10 ** (gainDb / 20);
78|}
79|
80|export interface AmbiencePrefs {
81|  level: string;
82|  volume: number;
83|}
84|
85|function validLevel(value: unknown): string | null {
86|  const ids = AMBIENCES.flatMap((ambience) => ambience.levels.map((level) => level.id));
87|  return typeof value === "string" && ids.includes(value) ? value : null;
88|}
89|
90|function validVolume(value: unknown): number | null {
91|  return typeof value === "number" && Number.isFinite(value) && value >= 0 && value <= 1
92|    ? value
93|    : null;
94|}
95|
96|// Anything invalid falls back to off at the default volume, never throws.
97|export function parseAmbiencePrefs(value: unknown): AmbiencePrefs {
98|  const fallback = { level: "off", volume: DEFAULT_AMBIENCE_VOLUME };
99|  if (typeof value !== "object" || value === null) return fallback;
100|  const { level, volume } = value as Record<string, unknown>;
101|  return {
102|    level: validLevel(level) ?? fallback.level,
103|    volume: validVolume(volume) ?? fallback.volume,
104|  };
